//! The YARA-L catalogues: the Unified Data Model (`data/catalogs/yaral/udm.toml`)
//! and Google's function list (`data/catalogs/yaral/functions.toml`), both
//! generated by `scripts/engine/sync_yaral_catalogs.py`. Each is parsed once per
//! process.

use serde::Deserialize;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

const UDM_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/data/catalogs/yaral/udm.toml"
));
const FUNCTIONS_TOML: &str = include_str!(concat!(
    env!("OPENTIDE_ASSETS"),
    "/data/catalogs/yaral/functions.toml"
));

/// The keywords of yara-l-1.0 "Lexical structure": the section names and the
/// operators. A keyword is never a rule name, meta key or variable
/// (`yaral_reserved_identifier`). Compared lower-cased.
pub const KEYWORDS: &[&str] = &[
    "rule",
    "meta",
    "setup",
    "events",
    "match",
    "outcome",
    "condition",
    "options",
    "export",
    "dedup",
    "order",
    "limit",
    "select",
    "unselect",
    "stage",
    "and",
    "or",
    "not",
    "nocase",
    "in",
    "regex",
    "cidr",
    "any",
    "all",
    "over",
    "by",
    "before",
    "after",
    "if",
    "of",
    "true",
    "false",
    "asc",
    "desc",
];

/// Whether `word` is a YARA-L keyword, in any case.
pub fn is_keyword(word: &str) -> bool {
    let lowered = word.to_ascii_lowercase();
    KEYWORDS.contains(&lowered.as_str())
}

#[derive(Debug, Clone, Deserialize)]
pub struct Field {
    pub name: String,
    #[serde(rename = "type")]
    pub ty: String,
    #[serde(default, rename = "enum")]
    pub is_enum: bool,
    #[serde(default)]
    pub repeated: bool,
    #[serde(default)]
    pub deprecated: bool,
    #[serde(default)]
    pub doc: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Message {
    pub name: String,
    #[serde(default)]
    pub doc: Option<String>,
    #[serde(default)]
    pub fields: Vec<Field>,
}

#[derive(Debug, Clone, Deserialize)]
struct EnumRow {
    name: String,
    values: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Roots {
    pub event: String,
    pub entity: String,
    pub detection: String,
}

#[derive(Debug, Deserialize)]
struct UdmFile {
    roots: Roots,
    #[serde(default)]
    free: Vec<String>,
    #[serde(default)]
    types: Vec<Message>,
    #[serde(default)]
    enums: Vec<EnumRow>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Function {
    pub name: String,
    #[serde(default)]
    pub namespace: Option<String>,
    pub signature: String,
    pub min_args: usize,
    #[serde(default)]
    pub max_args: Option<usize>,
    #[serde(default)]
    pub params: Vec<String>,
    #[serde(default)]
    pub result: Option<String>,
    #[serde(default)]
    pub availability: Vec<String>,
    #[serde(default)]
    pub aggregation: bool,
    #[serde(default)]
    pub summary: String,
    #[serde(default)]
    pub url: String,
}

impl Function {
    /// Whether the profile offers it (`rules` or `search`).
    pub fn available_in(&self, profile: crate::Profile) -> bool {
        self.availability
            .iter()
            .any(|a| a == profile.availability())
    }

    /// The function's own name, without its namespace.
    pub fn short_name(&self) -> &str {
        self.name.rsplit('.').next().unwrap_or(&self.name)
    }

    /// The parameter names of its signature, for signature help.
    pub fn parameters(&self) -> Vec<String> {
        let Some(open) = self.signature.find('(') else {
            return Vec::new();
        };
        let close = self.signature.rfind(')').unwrap_or(self.signature.len());
        self.signature[open + 1..close.max(open + 1)]
            .split(',')
            .map(|p| {
                p.trim()
                    .trim_start_matches('[')
                    .trim_end_matches(']')
                    .trim()
            })
            .filter(|p| !p.is_empty())
            .map(str::to_string)
            .collect()
    }
}

#[derive(Debug, Deserialize)]
struct FunctionsFile {
    #[serde(default)]
    functions: Vec<Function>,
}

/// What a type name denotes.
#[derive(Debug, Clone, Copy)]
pub enum TypeKind<'a> {
    /// A message with fields.
    Message(&'a Message),
    /// An enumerated type with its values.
    Enum(&'a str, &'a [String]),
    /// A scalar: `string`, `int64`, `bool`, ...
    Scalar(&'a str),
    /// Keys are the log's (`google.protobuf.Struct`), or the page gives the
    /// type no table: nothing below it is checked.
    Free,
}

pub struct Udm {
    pub roots: Roots,
    messages: BTreeMap<String, Message>,
    enums: BTreeMap<String, Vec<String>>,
    free: BTreeSet<String>,
}

const SCALARS: &[&str] = &[
    "string", "bool", "bytes", "int32", "int64", "uint32", "uint64", "double", "float",
];

impl Udm {
    #[expect(
        clippy::expect_used,
        reason = "the catalogs are compiled in with include_str! and parsed by the tests"
    )]
    pub fn cached() -> &'static Udm {
        static UDM: OnceLock<Udm> = OnceLock::new();
        UDM.get_or_init(|| {
            let file: UdmFile = toml::from_str(UDM_TOML).expect("data/catalogs/yaral/udm.toml");
            Udm {
                roots: file.roots,
                messages: file
                    .types
                    .into_iter()
                    .map(|m| (m.name.clone(), m))
                    .collect(),
                enums: file.enums.into_iter().map(|e| (e.name, e.values)).collect(),
                free: file.free.into_iter().collect(),
            }
        })
    }

    pub fn message(&self, name: &str) -> Option<&Message> {
        self.messages.get(name)
    }

    /// What `field`'s type is.
    pub fn kind_of<'a>(&'a self, field: &'a Field) -> TypeKind<'a> {
        if field.is_enum {
            return match self.enums.get_key_value(&field.ty) {
                Some((name, values)) => TypeKind::Enum(name, values),
                // An enum the page lists no values for (`Namespace`).
                None => TypeKind::Scalar("string"),
            };
        }
        self.kind_of_name(&field.ty)
    }

    pub fn kind_of_name<'a>(&'a self, ty: &'a str) -> TypeKind<'a> {
        if let Some(m) = self.messages.get(ty) {
            return TypeKind::Message(m);
        }
        if let Some((name, values)) = self.enums.get_key_value(ty) {
            return TypeKind::Enum(name, values);
        }
        if SCALARS.contains(&ty) {
            return TypeKind::Scalar(ty);
        }
        let _ = &self.free;
        TypeKind::Free
    }

    /// The root message of a path's first segment, and whether that segment
    /// is the data source (`udm`, `graph`, `detection`) rather than a field.
    #[expect(
        clippy::expect_used,
        reason = "udm.toml's roots name its messages: the catalog tests check it"
    )]
    pub fn root_for(&self, first: &str) -> (&Message, bool) {
        let (name, consumed) = match first {
            "udm" => (self.roots.event.as_str(), true),
            "graph" => (self.roots.entity.as_str(), true),
            "detection" => (self.roots.detection.as_str(), true),
            _ => (self.roots.event.as_str(), false),
        };
        (
            self.messages
                .get(name)
                .expect("udm.toml roots name messages"),
            consumed,
        )
    }

    /// The data sources a path may start with, for completion.
    pub const SOURCES: &'static [(&'static str, &'static str)] = &[
        ("udm", "The UDM event (the default source)"),
        ("graph", "The entity graph: entity context"),
        (
            "detection",
            "Detections, read by composite rules (detection.detection.rule_name)",
        ),
    ];
}

/// One step of a field path.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Segment {
    /// `.name`, at a byte span.
    Name(String, (usize, usize)),
    /// `["key"]`: a map key.
    Key((usize, usize)),
    /// `[0]`: a repeated field's element.
    Position((usize, usize)),
}

/// Where a field path leads.
#[derive(Debug, Clone, Default)]
pub struct Resolution<'a> {
    /// The last field the path names, when the catalogue has it.
    pub field: Option<&'a Field>,
    /// The type of the value the whole path reads.
    pub kind: Option<TypeKind<'a>>,
    /// The first segment the catalogue does not have: its index, and the
    /// message it was looked up in.
    pub unknown: Option<(usize, &'a str)>,
    /// Deprecated fields on the way, by segment index.
    pub deprecated: Vec<(usize, &'a Field)>,
    /// The path ends in a map key (`fields["k"]`, `ingestion_labels["k"]`).
    pub map_key: bool,
    /// The path went under a type whose keys are free.
    pub free: bool,
}

impl Udm {
    /// Walk `segments` from the event, entity or detection root.
    pub fn resolve(&self, segments: &[Segment]) -> Resolution<'_> {
        let mut out = Resolution::default();
        let Some(Segment::Name(first, _)) = segments.first() else {
            return out;
        };
        let (root, consumed) = self.root_for(first);
        let mut current = TypeKind::Message(root);
        let start = usize::from(consumed);
        for (i, segment) in segments.iter().enumerate().skip(start) {
            match segment {
                Segment::Name(name, _) => match current {
                    TypeKind::Message(message) => {
                        let Some(field) = message.fields.iter().find(|f| f.name == *name) else {
                            out.unknown = Some((i, message.name.as_str()));
                            return out;
                        };
                        if field.deprecated {
                            out.deprecated.push((i, field));
                        }
                        out.field = Some(field);
                        out.map_key = false;
                        current = self.kind_of(field);
                    }
                    TypeKind::Free => {
                        out.free = true;
                        out.kind = Some(TypeKind::Free);
                        return out;
                    }
                    TypeKind::Enum(..) | TypeKind::Scalar(_) => {
                        out.unknown = Some((i, out.field.map_or("", |f| f.ty.as_str())));
                        return out;
                    }
                },
                Segment::Key(_) => match current {
                    // A map entry or a label (`key`, `value`): the value.
                    TypeKind::Message(message) => {
                        let value = message.fields.iter().find(|f| f.name == "value");
                        let key = message.fields.iter().any(|f| f.name == "key");
                        match value {
                            Some(value) if key => {
                                current = self.kind_of(value);
                                out.map_key = true;
                            }
                            _ => {
                                out.free = true;
                                out.kind = Some(TypeKind::Free);
                                return out;
                            }
                        }
                    }
                    _ => {
                        out.free = true;
                        out.map_key = true;
                        out.kind = Some(TypeKind::Free);
                        return out;
                    }
                },
                Segment::Position(_) => {}
            }
            if matches!(current, TypeKind::Free) {
                out.free = true;
            }
        }
        out.kind = Some(current);
        out
    }

    /// The fields one can write after `segments` (completion), or the data
    /// sources at the root.
    pub fn members(&self, segments: &[Segment]) -> Option<&Message> {
        if segments.is_empty() {
            return self.messages.get(&self.roots.event);
        }
        if let [Segment::Name(first, _)] = segments {
            let (root, consumed) = self.root_for(first);
            if consumed {
                return Some(root);
            }
        }
        match self.resolve(segments) {
            Resolution {
                kind: Some(TypeKind::Message(m)),
                unknown: None,
                ..
            } => Some(m),
            _ => None,
        }
    }
}

pub struct Functions {
    by_name: BTreeMap<String, Function>,
}

impl Functions {
    #[expect(
        clippy::expect_used,
        reason = "the catalogs are compiled in with include_str! and parsed by the tests"
    )]
    pub fn cached() -> &'static Functions {
        static FUNCTIONS: OnceLock<Functions> = OnceLock::new();
        FUNCTIONS.get_or_init(|| {
            let file: FunctionsFile =
                toml::from_str(FUNCTIONS_TOML).expect("data/catalogs/yaral/functions.toml");
            Functions {
                by_name: file
                    .functions
                    .into_iter()
                    .map(|f| (f.name.clone(), f))
                    .collect(),
            }
        })
    }

    pub fn get(&self, name: &str) -> Option<&Function> {
        self.by_name.get(name)
    }

    pub fn all(&self) -> impl Iterator<Item = &Function> {
        self.by_name.values()
    }

    /// Whether `namespace` is one of Google's function namespaces.
    pub fn is_namespace(&self, namespace: &str) -> bool {
        self.by_name
            .values()
            .any(|f| f.namespace.as_deref() == Some(namespace))
    }

    /// The functions of `namespace`.
    pub fn in_namespace<'a>(&'a self, namespace: &'a str) -> impl Iterator<Item = &'a Function> {
        self.by_name
            .values()
            .filter(move |f| f.namespace.as_deref() == Some(namespace))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn path(p: &str) -> Vec<Segment> {
        p.split('.')
            .map(|s| Segment::Name(s.to_string(), (0, 0)))
            .collect()
    }

    #[test]
    fn catalogues_load() {
        let udm = Udm::cached();
        assert!(udm.message("Noun").is_some());
        assert!(udm.message("Collection").is_some());
        let functions = Functions::cached();
        assert!(functions.get("strings.to_lower").is_some());
        assert!(functions.get("count").is_some_and(|f| f.aggregation));
        assert!(functions.is_namespace("re"));
    }

    #[test]
    fn paths_resolve_through_the_type_graph() {
        let udm = Udm::cached();
        let r = udm.resolve(&path("metadata.event_type"));
        assert!(r.unknown.is_none());
        assert!(
            matches!(r.kind, Some(TypeKind::Enum(_, values)) if values.iter().any(|v| v == "PROCESS_LAUNCH"))
        );
        let r = udm.resolve(&path("principal.process.parent_process.file.full_path"));
        assert!(r.unknown.is_none(), "{r:?}");
        assert_eq!(
            udm.resolve(&path("principal.hostnam")).unknown.map(|u| u.0),
            Some(1)
        );
        assert!(
            udm.resolve(&path("graph.entity.hostname"))
                .unknown
                .is_none()
        );
        assert!(udm.resolve(&path("udm.target.ip")).unknown.is_none());
        assert!(
            udm.resolve(&path("detection.detection.rule_name"))
                .unknown
                .is_none()
        );
        assert!(
            udm.resolve(&path(
                "detection.collection_elements.references.event.principal.hostname"
            ))
            .unknown
            .is_none()
        );
        assert!(
            udm.resolve(&path("metadata.event_timestamp.seconds"))
                .unknown
                .is_none()
        );
        // Struct keys are the log's.
        assert!(udm.resolve(&path("additional.fields.anything")).free);
    }
}
